import React from 'react';
import { Container, Row, Col, Table, Button } from 'reactstrap';
import { Link } from 'react-router-dom';
import useFetch from '../../hooks/useFetch';
import { BASE_URL } from '../../utils/config';
import './manage-tour.css'; // Nếu bạn muốn thêm css riêng

const ManageTours = () => {
   // 1. Lấy danh sách tour từ API
   const { data: tours, loading, error } = useFetch(`${BASE_URL}/tours`);

   // 2. Hàm xử lý xóa Tour
   const deleteHandler = async (id) => {
      if (window.confirm("Bạn có chắc chắn muốn xóa tour này?")) {
         const token = localStorage.getItem('token');
         try {
            const res = await fetch(`${BASE_URL}/tours/${id}`, {
               method: 'DELETE',
               headers: {
                  'Authorization': `Bearer ${token}`
               }
            });

            const result = await res.json();
            if (res.ok) {
               alert("Xóa thành công!");
               window.location.reload(); // Load lại trang để cập nhật danh sách
            } else {
               alert(result.message);
            }
         } catch (err) {
            alert("Lỗi server không thể xóa!");
         }
      }
   };

   return (
      <section>
         <Container>
            <Row>
               {/* TIÊU ĐỀ VÀ NÚT TẠO MỚI */}
               <Col lg='12' className="d-flex justify-content-between align-items-center mb-4 mt-5">
                  <h2 className="manage__title">Danh sách Tour hiện có</h2>
                  <Link to='/admin/tours/create'>
                     <Button className='btn primary__btn'>+ Thêm Tour Mới</Button>
                  </Link>
               </Col>

               <Col lg='12'>
                  <Table striped bordered hover responsive className="text-center align-middle">
                     <thead>
                        <tr>
                           <th>Ảnh bìa</th>
                           <th>Tên Tour</th>
                           <th>Thành phố</th>
                           <th>Giá ($)</th>
                           <th>Nổi bật</th>
                           <th>Thao tác</th>
                        </tr>
                     </thead>
                     <tbody>
                        {loading && <tr><td colSpan='6'>Đang tải dữ liệu...</td></tr>}
                        {error && <tr><td colSpan='6' className="text-danger">{error}</td></tr>}
                        
                        {!loading && !error && tours?.map(tour => (
                           <tr key={tour._id}>
                              <td>
                                 <img 
                                    src={`http://localhost:8000/static-number-one/${tour.photo}`} 
                                    alt="tour-img" 
                                    style={{ width: '60px', height: '40px', objectFit: 'cover', borderRadius: '4px' }}
                                 />
                              </td>
                              <td className="text-start">{tour.title}</td>
                              <td>{tour.city}</td>
                              <td><strong>{tour.price}</strong></td>
                              <td>{tour.featured ? <span className="text-success">Yes</span> : 'No'}</td>
                              <td>
                                 <div className="d-flex justify-content-center gap-3">
                                    {/* NÚT SỬA: Dẫn tới trang CreateTour kèm theo ID */}
                                    <Link to={`/admin/update-tour/${tour._id}`}>
                                       <button className="btn btn-warning btn-sm text-white">
                                          Sửa
                                       </button>
                                    </Link>
                                    
                                    {/* NÚT XÓA */}
                                    <button 
                                       className="btn btn-danger btn-sm" 
                                       onClick={() => deleteHandler(tour._id)}
                                    >
                                       Xóa
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </Table>
               </Col>
            </Row>
         </Container>
      </section>
   );
};

export default ManageTours;
